describe('Accessibility Click Targets', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should have click targets that are at least 44x44px', () => {
        cy.get('button, a, input[type="button"], input[type="submit"]').each(($el) => {
            const width = $el.width();
            const height = $el.height();
            expect(width).to.be.gte(44);
            expect(height).to.be.gte(44);
        });
    });

    it('should not have any click targets smaller than 44x44px', () => {
        cy.get('button, a, input[type="button"], input[type="submit"]').each(($el) => {
            const width = $el.width();
            const height = $el.height();
            if (width < 44 || height < 44) {
                throw new Error(`Click target ${$el.prop('outerHTML')} is smaller than 44x44px`);
            }
        });
    });
});
